D=current_data();changes=[];records=[]
sources=[
 dated_source('src-stellaris-machineage-official-models','Machine Age: virtual workers and Synthetic Fertility','Paradox Development Studio','https://store.steampowered.com/news/posts/?appids=281990&enddate=1712228443&feed=steam_community_announcements','Developer passages: Virtuality fills open jobs with virtual pops and turns unemployed represented pops off; Synthetic Fertility builds an Identity Repository while seeking robotic bodies for minds threatened by disease.','Historically documented qualitative models, not a claim that later balance rules or every off-screen virtual life are known.',kind='developer_documentation',access='Indexed developer Virtuality and Synthetic Fertility passages read'),
 dated_source('src-smac-manual-factions','Alpha Centauri manual: University and Morgan','Firaxis / Electronic Arts','https://manualmachine.com/gamespc/sidmeiersalphacentauri/1118510-user-manual/','Manual passages: University research/free information exchange; Morgan corporate organization and laissez-faire economics.','Manual mirror; configurable policies and technological stages remain separate from starting faction identity.',kind='primary_text',access='Indexed faction-description manual passages read'),
 dated_source('src-endless2-official-factions','Endless Space 2: faction premises','Amplitude Studios','https://www.endless-space.com/','Official faction descriptions identify United Empire resource competition, Horatio’s cloning project and Riftborn origins outside the material universe.','Short faction premises, not ordinary household rights or final player outcomes.',kind='official_reference',access='Indexed official faction descriptions read'),
 dated_source('src-loa-official-manual','Sword of the Stars II: End of Flesh manual','Kerberos Productions','https://www.kerberos-productions.com/sots2_motd/SotS2-EOF_v1-0_301112.pdf','Manual passage identifies Loa cyber-sapience and their escape beyond the reach of former owners.','Bounded indexed lore passage; household energy/component entitlements are not specified.',kind='primary_text',access='Indexed Loa emancipation passage read'),
 dated_source('src-stellaris-official-synthetic-evolution','Utopia: Synthetic Evolution','Paradox Interactive','https://www.paradoxinteractive.com/media/press-releases/paradox-interactive/ascend-to-a-higher-plane-with-stellaris-console-edition-utopia-out-now','Official release description offers giving up biological forms through Synthetic Evolution.','The ascension option does not itself specify selected living standards or ownership.',kind='official_reference',access='Indexed official ascension-options paragraph read'),
]
