(.3,.25,.35),([-.7,.95],[-.7,.8],[.03,.85]),('Advanced tools allow provision but leave ordinary access conditional and uncertain.','Human-derived colony agency coexists with autonomous operational tools.','Enhanced workers and useful cognitive/caring roles remain work.'),
