(-.6,.55,.6),([-.98,.7],[-.8,1],[.08,.98]),('Shared sustaining support is a projection from achieved technical/biological integration.','Human-derived collective and planetary biology are central, not automatically external AI.','Active persons may retain stewardship, coordination and care after routine substitution.'),
